// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { recorded, redone, undone } from "../../../main/frontend/graph-explorer/history-stack.ts";

const empty = { past: [], future: [] };

test("recording a change keeps the newest snapshots and forgets what could be redone", () => {
  const stacks = recorded(recorded(recorded({ past: [], future: ["x"] }, "a", 2), "b", 2), "c", 2);
  assert.deepEqual(stacks, { past: ["b", "c"], future: [] });
});

test("undo returns the last snapshot and keeps the current state for redo; redo does the reverse", () => {
  const step = undone({ past: ["a", "b"], future: [] }, "now", 32);
  assert.deepEqual(step, { snapshot: "b", stacks: { past: ["a"], future: ["now"] } });
  assert.deepEqual(redone(step.stacks, "b", 32), { snapshot: "now", stacks: { past: ["a", "b"], future: [] } });
});

test("there is nothing to undo or redo on empty stacks", () => {
  assert.equal(undone(empty, "now", 32), null);
  assert.equal(redone(empty, "now", 32), null);
});
